const folderName = $('Set Variables').item.json.folderName;
const response = $input.first().json;
const values = response.values || [];

const dataRowCount = values.length > 1 ? values.length - 1 : 0;
const nextNo = dataRowCount + 1;

if (values.length < 2) {
  return [{ json: { found: false, status: null, nextNo } }];
}

const headers = values[0];
const folderNameIdx = headers.indexOf('Folder Name');
const statusIdx = headers.indexOf('Status');

if (folderNameIdx === -1) {
  throw new Error('Cột "Folder Name" không tìm thấy trong sheet. Kiểm tra lại header row.');
}

const match = values.slice(1).find(row => row[folderNameIdx] === folderName);

if (match) {
  return [{ json: { found: true, status: statusIdx !== -1 ? (match[statusIdx] || null) : null, nextNo } }];
}

return [{ json: { found: false, status: null, nextNo } }];

const files = $input.first().json.files || [];

if (files.length === 0) {
  return [];
}

return files.map(file => ({ json: { id: file.id, name: file.name, mimeType: file.mimeType } }));

const items = $input.all();
let combinedText = '';

for (const item of items) {
  const binaryData = item.binary?.data;
  if (binaryData) {
    const base64Content = binaryData.data;
    const text = Buffer.from(base64Content, 'base64').toString('utf-8');
    combinedText += `\n--- File: ${item.json.name} ---\n${text}\n`;
  }
}

const maxLength = 20000;
if (combinedText.length > maxLength) {
  combinedText = combinedText.substring(0, maxLength) + '\n... [nội dung bị cắt bớt]';
}

return [{
  json: {
    markdownContent: combinedText,
    quizTitle: $('Set Variables').item.json.folderName,
    description: `Quiz được tạo tự động từ folder ${$('Set Variables').item.json.folderName}`,
    questionsPerFile: 15,
    fileName: $('Set Variables').item.json.folderName
  }
}];

