={{ (() => {
  const formId = $json.formId;
  const questions = $('Parse AI Quiz Response').item.json.questions;
  const description = $('Parse AI Quiz Response').item.json.description;
  const requests = [];
  if (description) {
    requests.push({ updateFormInfo: { info: { description }, updateMask: 'description' } });
  }
  requests.push({ updateSettings: { settings: { quizSettings: { isQuiz: true } }, updateMask: 'quizSettings.isQuiz' } });
  questions.forEach((q, index) => {
    const options = Object.entries(q.options || {}).map(([key, value]) => ({ value: `${key}. ${value}` }));
    const correctKey = q.correctAnswer;
    const correctOptionValue = `${correctKey}. ${(q.options || {})[correctKey]}`;
    requests.push({
      createItem: {
        item: {
          title: q.question,
          description: q.explanation ? `💡 Giải thích: ${q.explanation}` : '',
          questionItem: {
            question: {
              required: true,
              grading: {
                pointValue: 1,
                correctAnswers: { answers: [{ value: correctOptionValue }] },
                whenRight: { text: '✅ Chính xác!' },
                whenWrong: { text: `❌ Đáp án đúng là: ${correctOptionValue}` }
              },
              choiceQuestion: { type: 'RADIO', options, shuffle: false }
            }
          }
        },
        location: { index }
      }
    });
  });
  return { requests };
})() }}
